def load_allowed_roots():
    raw_roots = os.getenv(
        "REPO_DOCTOR_ALLOWED_ROOTS",
        settings.allowed_roots,
    )

    roots = []

    for raw_root in raw_roots.split(
        os.pathsep
    ):
        raw_root = raw_root.strip()

        if not raw_root:
            continue

        root = Path(
            raw_root
        ).resolve()

        if root.exists() and root.is_dir():
            roots.append(root)

    if not roots:
        raise RuntimeError(
            "没有有效的允许访问目录。"
            "请设置 REPO_DOCTOR_ALLOWED_ROOTS"
        )

    return roots

